def generate(self, prompts, sampling_params, use_tqdm=True):
    pbar = tqdm(total=len(prompts), ...)                     # (1) 进度条
    if not isinstance(sampling_params, list):
        sampling_params = [sampling_params] * len(prompts)    # (2) 广播单参数到所有 prompt
    for prompt, sp in zip(prompts, sampling_params):
        self.add_request(prompt, sp)                          # (3) 将请求加入 waiting 队列
    outputs = {}
    prefill_throughput = decode_throughput = 0.
    while not self.is_finished():                            # (4) 主循环：直到所有 seq 完成
        t = perf_counter()
        output, num_tokens = self.step()                     # (5) 单步调度+推理+后处理
        if num_tokens > 0:
            prefill_throughput = num_tokens / (perf_counter() - t)   # (6a) Prefill 吞吐
        else:
            decode_throughput = -num_tokens / (perf_counter() - t)  # (6b) Decode 吞吐
        pbar.set_postfix({"Prefill": ..., "Decode": ...})   # (7) 实时显示吞吐
        for seq_id, token_ids in output:
            outputs[seq_id] = token_ids                     # (8) 收集完成输出
            pbar.update(1)
    outputs = [outputs[seq_id] for seq_id in sorted(outputs.keys())]  # (9) 按 seq_id 排序
    outputs = [{
        "text": self.tokenizer.decode(token_ids),           # (10) 解码为文本
        "token_ids": token_ids                              # (11) 保留原始 token ids
    } for token_ids in outputs]
    return outputs
